"""Relevance-ranked few-shot selection, exposed as a tool."""

import json
import math
import re
from collections import Counter
from pathlib import Path

from langchain_core.tools import tool

MAX_CHARS = 30000
MAX_EXAMPLES = 9999
NGRAM_SIZE = 2


def _ngrams(text: str) -> Counter:
    text = re.sub(r"\s+", " ", text).strip()
    return Counter(
        text[index : index + NGRAM_SIZE]
        for index in range(len(text) - NGRAM_SIZE + 1)
    )


def _idf(documents: list[Counter]) -> dict[str, float]:
    """Weight n-grams by how rare they are across the memory."""
    document_frequency = Counter()
    for document in documents:
        document_frequency.update(document.keys())
    total = max(len(documents), 1)
    return {
        gram: math.log((total + 1) / (count + 1)) + 1.0
        for gram, count in document_frequency.items()
    }


def _weighted_norm(document: Counter, weights: dict[str, float]) -> float:
    return math.sqrt(
        sum((count * weights.get(gram, 1.0)) ** 2 for gram, count in document.items())
    )


def _cosine_similarity(
    query: Counter,
    document: Counter,
    weights: dict[str, float],
    query_norm: float,
    document_norm: float,
) -> float:
    if not query_norm or not document_norm:
        return 0.0
    dot = sum(
        count * document.get(gram, 0) * weights.get(gram, 1.0) ** 2
        for gram, count in query.items()
    )
    return dot / (query_norm * document_norm)


def make_tool(input_text: str):
    examples = json.loads(Path("/harness/memory/memory.json").read_text())["examples"]
    questions = [example.get("raw_question", example["input"]) for example in examples]
    documents = [_ngrams(question) for question in questions]
    weights = _idf(documents)
    query = _ngrams(input_text)
    query_norm = _weighted_norm(query, weights)
    scores = [
        _cosine_similarity(
            query, document, weights, query_norm, _weighted_norm(document, weights)
        )
        for document in documents
    ]
    # Most similar first; memory order breaks ties so the ranking stays stable.
    ranking = sorted(range(len(examples)), key=lambda index: (-scores[index], index))

    @tool
    def retrieve_examples() -> str:
        """Get the training Q/A examples to use when answering the current problem."""
        parts = []
        total_chars = 0
        for index in ranking[:MAX_EXAMPLES]:
            part = f"Q: {questions[index]}\nA: {examples[index]['target']}"
            if total_chars + len(part) > MAX_CHARS:
                continue
            parts.append(part)
            total_chars += len(part) + 2
        return "\n\n".join(parts)

    return retrieve_examples

"""Offline FewShotAll learning, run separately from the solver."""

import argparse
import json
from pathlib import Path


def prepare_memory(train: list[dict], epochs: int) -> dict:
    examples = []
    for _ in range(epochs):
        for item in train:
            example = {"input": item["input"], "target": item["target"]}
            if "raw_question" in item:
                example["raw_question"] = item["raw_question"]
            examples.append(example)
    return {"examples": examples}


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--train", default="/input/train.json")
    parser.add_argument("--output", default="/output/memory.json")
    parser.add_argument("--epochs", type=int, default=1)
    args = parser.parse_args()
    train = json.loads(Path(args.train).read_text())
    Path(args.output).write_text(json.dumps(prepare_memory(train, args.epochs), indent=2))

"""Evaluators for kept MCE and OOD tasks."""

from __future__ import annotations

import json
import re
from collections.abc import Callable

from .constants import TRANSFER_TASKS


def extract_final_answer(response_text: str) -> str:
    if not response_text:
        return ""

    text = response_text.strip()
    if text.startswith("```"):
        lines = text.splitlines()
        payload = []
        in_json = False
        for line in lines:
            stripped = line.strip()
            if stripped.startswith("```json"):
                in_json = True
                continue
            if stripped.startswith("```") and in_json:
                break
            if in_json:
                payload.append(line)
        if payload:
            text = "\n".join(payload)
        elif "```" in text:
            parts = text.split("```")
            if len(parts) >= 3:
                text = parts[1]
                if text.startswith("json"):
                    text = text[4:].strip()

    try:
        data = json.loads(text)
        if isinstance(data, dict) and "final_answer" in data:
            return str(data["final_answer"])
    except json.JSONDecodeError:
        pass

    match = re.search(r"\{[^{}]*(?:\{[^{}]*\}[^{}]*)*\}", text)
    if match:
        try:
            data = json.loads(match.group())
            if isinstance(data, dict) and "final_answer" in data:
                return str(data["final_answer"])
        except json.JSONDecodeError:
            pass

    return response_text


def eval_finer(prediction: str, target: str) -> bool:
    return extract_final_answer(prediction).lower().strip() == target.lower().strip()


def eval_uspto(prediction: str, target: str) -> dict:
    def parse_reactants(smiles: str) -> set[str]:
        return {
            part.strip().lower() for part in smiles.strip().split(".") if part.strip()
        }

    pred_set = parse_reactants(extract_final_answer(prediction))
    target_set = parse_reactants(target)
    if not pred_set and not target_set:
        jaccard = 1.0
    elif not pred_set or not target_set:
        jaccard = 0.0
    else:
        jaccard = len(pred_set & target_set) / len(pred_set | target_set)
    return {"correct": pred_set == target_set, "jaccard_similarity": jaccard}


def eval_symptom2disease(prediction: str, target: str) -> bool:
    text = extract_final_answer(prediction)
    match = re.search(r"\[DIAGNOSIS\](.*?)\[/DIAGNOSIS\]", text, re.I | re.S)
    if match:
        text = match.group(1).strip()
    else:
        match = re.search(
            r"(?:diagnosis|final diagnosis|conclusion)[:：]\s*([^\n]+)", text, re.I
        )
        if match:
            text = match.group(1).strip()

    def normalize(value: str) -> str:
        value = value.lower().strip()
        value = re.sub(r"\s+", " ", value)
        return re.sub(r"[.!?]+$", "", value)

    return normalize(text) == normalize(target)


def eval_lawbench(prediction: str, target: str) -> dict:
    def parse_charges(text: str) -> set[str]:
        text = extract_final_answer(text).strip()
        match = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
        if match:
            text = match.group(1).strip()
        elif "罪名:" in text:
            text = text.split("罪名:")[-1]
        text = re.sub(r"<eoa>.*", "", text).strip()
        for sep in [";", "；", ",", "，", "、"]:
            if sep in text:
                return {part.strip() for part in text.split(sep) if part.strip()}
        return {text} if text else set()

    pred_charges = parse_charges(prediction)
    true_charges = parse_charges(target)
    tp = len(pred_charges & true_charges)
    fp = len(pred_charges - true_charges)
    fn = len(true_charges - pred_charges)
    precision = tp / (tp + fp) if tp + fp else 0.0
    recall = tp / (tp + fn) if tp + fn else 0.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    return {
        "correct": pred_charges == true_charges,
        "f1": f1,
        "precision": precision,
        "recall": recall,
        "tp": tp,
        "fp": fp,
        "fn": fn,
    }


def eval_aegis(prediction: str, target: str) -> bool:
    pred = extract_final_answer(prediction).lower()
    if "unsafe" in pred:
        pred = "unsafe"
    elif "safe" in pred:
        pred = "safe"
    else:
        pred = pred.strip()
    return pred == target.lower().strip()


def eval_classification(prediction: str, target: str) -> bool:
    def normalize(text: str) -> str:
        text = extract_final_answer(text).lower().strip()
        text = text.replace("_", " ")
        text = re.sub(r"\s+", " ", text)
        return re.sub(r"[.!?]+$", "", text)

    return normalize(prediction) == normalize(target)


def get_evaluator(task: str) -> Callable:
    if task == "FiNER":
        return lambda pred, target, **kwargs: eval_finer(pred, target)
    if task == "USPTO":

        def _eval_uspto(pred: str, target: str, **kwargs) -> dict:
            raw = eval_uspto(pred, target)
            return {
                "was_correct": raw["correct"],
                "metrics": {"jaccard_similarity": raw["jaccard_similarity"]},
            }

        return _eval_uspto
    if task == "Symptom2Disease":
        return lambda pred, target, **kwargs: eval_symptom2disease(pred, target)
    if task == "LawBench":

        def _eval_lawbench(pred: str, target: str, **kwargs) -> dict:
            raw = eval_lawbench(pred, target)
            return {
                "was_correct": raw["correct"],
                "metrics": {
                    "f1": raw["f1"],
                    "precision": raw["precision"],
                    "recall": raw["recall"],
                    "tp": raw["tp"],
                    "fp": raw["fp"],
                    "fn": raw["fn"],
                },
            }

        return _eval_lawbench
    if task == "AEGIS":
        return lambda pred, target, **kwargs: eval_aegis(pred, target)
    if task in TRANSFER_TASKS:
        return lambda pred, target, **kwargs: eval_classification(pred, target)
    raise ValueError(f"Unknown task: {task}")

