import json, re, collections
RUNS = {
 'base':'9f49dd7221d29df0c6f8b80f8f04a8b2b2b607f7',
 'r1':'8a4e7e02ef6677b8b23161b60a8e92d7d5c9c347',
 'r2':'84ec2cc228a15743611ceb178336561ddcb30aaa',
 'r3':'c40638ad8987bbe0bbf5fb73ce00ea06886caaaa',
 'r4':'91f82d6416679b031eb200bcf2664557237a854f',
 'r5':'b31e34dad8ab52401cb7424d32437a21c135b24b',
}
SEPS=[";","；",",","，","、"]
def parse(text):
    text=str(text).strip()
    m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if m: text=m.group(1).strip()
    elif "罪名:" in text: text=text.split("罪名:")[-1]
    text=re.sub(r"<eoa>.*","",text).strip()
    for sep in SEPS:
        if sep in text: return {p.strip() for p in text.split(sep) if p.strip()}
    return {text} if text else set()

for name,run in RUNS.items():
    mem=json.load(open(f'/workspace/runs/{run}/LawBench/memory.json'))['examples']
    stored=[parse(e['target']) for e in mem]
    stored=[s for s in stored if s]
    uniq=[]
    seen=set()
    for s in stored:
        k=tuple(sorted(s))
        if k not in seen: seen.add(k); uniq.append(s)
    rows=[json.loads(l) for l in open(f'/workspace/runs/{run}/results/samples.jsonl')]
    rs=[r for r in rows if r['task']=='LawBench']
    stats=collections.Counter()
    ex_win=[]; ex_harm=[]
    for r in rs:
        P=parse(r['prediction']); T=parse(r['target'])
        if not P: stats['empty_pred']+=1; 
        if P==T:
            # would the rule break it?
            cands=[A for A in uniq if P<A]
            if cands:
                stats['correct_with_superset']+=1
            continue
        if not P: continue
        ok=T
        cands=[A for A in uniq if P<A]
        if len(cands)==1:
            newp=cands[0]
            if newp==T: stats['exactly1_win']+=1; ex_win.append((r['example_index'],r['sample_index'],sorted(P),sorted(T)))
            else: stats['exactly1_other']+=1; ex_harm.append((r['example_index'],r['sample_index'],sorted(P),sorted(T),sorted(newp)))
        elif len(cands)>1:
            # smallest added
            best=min(cands,key=lambda A:len(A-P))
            minimal=[A for A in cands if len(A-P)==len(best-P)]
            if len(minimal)==1:
                if best==T: stats['smallest_win']+=1
                else: stats['smallest_other']+=1
            else: stats['ambiguous']+=1
        else:
            stats['no_superset']+=1
    print(f"--- {name}: {len(rs)} samples, correct={sum(1 for r in rs if parse(r['prediction'])==parse(r['target']))}")
    print('   ',dict(stats))
    if ex_win: print('    wins:',ex_win[:8])
