 'r3':'c40638ad8987bbe0bbf5fb73ce00ea06886caaaa',
 'r4':'91f82d6416679b031eb200bcf2664557237a854f',
 'r5':'b31e34dad8ab52401cb7424d32437a21c135b24b',
}
SEPS=[";","；",",","，","、"]
def parse(text):
    text=str(text).strip()
    m=re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if m: text=m.group(1).strip()
    elif "罪名:" in text: text=text.split("罪名:")[-1]
    text=re.sub(r"<eoa>.*","",text).strip()
    for sep in SEPS:
        if sep in text: return {p.strip() for p in text.split(sep) if p.strip()}
    return {text} if text else set()
def lev(a,b):
    if a==b: return 0
    prev=list(range(len(b)+1))
    for i,ca in enumerate(a,1):
        cur=[i]
        for j,cb in enumerate(b,1):
            cur.append(min(prev[j]+1,cur[j-1]+1,prev[j-1]+(ca!=cb)))
        prev=cur
    return prev[-1]
for K in (1,2,3):
    print(f'===== max edit distance {K}')
    tot=collections.Counter()
    for name,run in RUNS.items():
        mem=json.load(open(f'/workspace/runs/{run}/LawBench/memory.json'))['examples']
        stored=set()
        for e in mem:
            stored.add(str(e['target']).strip())
            stored.update(parse(e['target']))
        stored={s for s in stored if len(s)>=2}
        rows=[json.loads(l) for l in open(f'/workspace/runs/{run}/results/samples.jsonl')]
        rs=[r for r in rows if r['task']=='LawBench']
        w2r=r2w=0; detail=[]
        for r in rs:
            P,T=parse(r['prediction']),parse(r['target'])
            if not P: continue
            newP=set()
            changed=False
            for p in P:
                if p in stored: newP.add(p); continue
                near=[s for s in stored if abs(len(s)-len(p))<=K and lev(p,s)<=K]
                if len(near)==1:
                    newP.add(near[0]); changed=True
                else:
                    newP.add(p)
            if not changed: continue
            if newP==T and P!=T: w2r+=1; detail.append(('WIN',r['example_index'],r['sample_index'],sorted(P),sorted(newP),sorted(T)))
            elif P==T and newP!=T: r2w+=1; detail.append(('HARM',r['example_index'],r['sample_index'],sorted(P),sorted(newP),sorted(T)))
        tot['w2r']+=w2r; tot['r2w']+=r2w
        print(f'  {name}: wrong->right {w2r}  right->wrong {r2w}')
        if name=='r5':
            for d in detail[:14]: print('     ',d)
    print('  TOTAL',dict(tot))
